// HTML Email Builder v2
// Handles all 3 possible output structures from group-by-category node

function formatDate(dateStr) {
  const d = dateStr ? new Date(dateStr) : new Date();
  return d.toLocaleDateString("en-US", {
    weekday: "long", year: "numeric", month: "long", day: "numeric",
  });
}

function escapeHtml(str) {
  return String(str || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const CATEGORY_COLORS = {
  "AI & Tech":  "#4F46E5",
  "Business":   "#0F766E",
  "Science":    "#7C3AED",
  "World News": "#B45309",
  "General":    "#4B5563",
};

function categoryColor(cat) {
  return CATEGORY_COLORS[cat] || "#4B5563";
}

// Read input - handle all possible structures
const allItems = $input.all();
const today    = formatDate();

let categoryList = [];
const firstItem = allItems[0]?.json || {};

if (Array.isArray(firstItem.categories) && firstItem.categories.length > 0) {
  // Single item with categories array
  categoryList = firstItem.categories;
} else if (firstItem.category && Array.isArray(firstItem.articles)) {
  // One item per category (flat)
  categoryList = allItems.map(item => item.json);
} else {
  // Nested categories key per item
  for (const item of allItems) {
    const d = item.json;
    if (Array.isArray(d.categories)) {
      categoryList.push(...d.categories);
    }
  }
}

const totalArticles = categoryList.reduce(
  (sum, cat) => sum + (cat.articles?.length || 0), 0
);

// Build sections
let sectionsHtml = "";

for (const catItem of categoryList) {
  const category = catItem.category;
  const articles = catItem.articles || [];
  if (!articles.length) continue;

  const color = categoryColor(category);

  sectionsHtml += `
    <tr>
      <td style="padding: 32px 0 12px 0;">
        <table width="100%" cellpadding="0" cellspacing="0" border="0">
          <tr>
            <td style="border-left: 4px solid ${color}; padding-left: 14px;">
              <span style="font-family:Arial,sans-serif;font-size:11px;font-weight:bold;
                letter-spacing:1.5px;text-transform:uppercase;color:${color};">
                ${escapeHtml(category)}
              </span>
            </td>
            <td style="font-family:Arial,sans-serif;font-size:11px;color:#9CA3AF;
              text-align:right;vertical-align:middle;">
              ${articles.length} article${articles.length !== 1 ? "s" : ""}
            </td>
          </tr>
        </table>
        <div style="border-bottom:1px solid #E5E7EB;margin-top:10px;"></div>
      </td>
    </tr>`;

  for (const article of articles) {
    const title       = escapeHtml(article.title);
    const link        = article.link || "#";
    const summary     = escapeHtml(article.summary);
    const author      = escapeHtml(article.author);
    const publishedAt = article.publishedAt ? formatDate(article.publishedAt) : "";

    sectionsHtml += `
    <tr>
      <td style="padding:16px 0 20px 0;border-bottom:1px solid #F3F4F6;">
        <a href="${link}" style="font-family:Arial,sans-serif;font-size:16px;
          font-weight:bold;color:#111827;text-decoration:none;
          line-height:1.4;display:block;margin-bottom:8px;">${title}</a>
        <p style="font-family:Arial,sans-serif;font-size:14px;color:#374151;
          line-height:1.7;margin:0 0 10px 0;">${summary}</p>
        <p style="font-family:Arial,sans-serif;font-size:12px;color:#9CA3AF;margin:0;">
          ${author ? `<strong style="color:#6B7280;">${author}</strong>` : ""}
          ${author && publishedAt ? " &middot; " : ""}
          ${publishedAt}
          &nbsp;&nbsp;
          <a href="${link}" style="color:${color};text-decoration:none;font-size:12px;">
            Read full article &rarr;
          </a>
        </p>
      </td>
    </tr>`;
  }
}

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Your Daily AI Digest</title>
</head>
<body style="margin:0;padding:0;background-color:#F9FAFB;">
  <table width="100%" cellpadding="0" cellspacing="0" border="0"
         style="background-color:#F9FAFB;padding:32px 16px;">
    <tr><td align="center">
      <table width="620" cellpadding="0" cellspacing="0" border="0"
             style="background-color:#FFFFFF;border-radius:8px;
                    border:1px solid #E5E7EB;max-width:620px;width:100%;">

        <tr>
          <td style="background-color:#111827;border-radius:8px 8px 0 0;
                     padding:32px 36px 28px 36px;">
            <p style="font-family:Arial,sans-serif;font-size:11px;font-weight:bold;
              letter-spacing:2px;text-transform:uppercase;color:#6B7280;margin:0 0 8px 0;">
              Your Daily Digest
            </p>
            <h1 style="font-family:Arial,sans-serif;font-size:26px;font-weight:bold;
              color:#FFFFFF;margin:0 0 12px 0;line-height:1.2;">${today}</h1>
            <p style="font-family:Arial,sans-serif;font-size:13px;color:#9CA3AF;margin:0;">
              ${totalArticles} article${totalArticles !== 1 ? "s" : ""} summarised across
              ${categoryList.length} categor${categoryList.length !== 1 ? "ies" : "y"}
              &mdash; no fluff, just signal.
            </p>
          </td>
        </tr>

        <tr>
          <td style="padding:0 36px 8px 36px;">
            <table width="100%" cellpadding="0" cellspacing="0" border="0">
              ${sectionsHtml}
            </table>
          </td>
        </tr>

        <tr>
          <td style="background-color:#F9FAFB;border-top:1px solid #E5E7EB;
                     border-radius:0 0 8px 8px;padding:24px 36px;text-align:center;">
            <p style="font-family:Arial,sans-serif;font-size:12px;color:#6B7280;margin:0 0 12px 0;">
              Sources: &nbsp;
              <a href="https://techcrunch.com" style="color:#4F46E5;text-decoration:none;">TechCrunch</a>
              &nbsp;&middot;&nbsp;
              <a href="https://news.ycombinator.com" style="color:#4F46E5;text-decoration:none;">Hacker News</a>
              &nbsp;&middot;&nbsp;
              <a href="https://technologyreview.com" style="color:#4F46E5;text-decoration:none;">MIT Tech Review</a>
            </p>
            <div style="border-top:1px solid #E5E7EB;margin:12px 0;"></div>
            <p style="font-family:Arial,sans-serif;font-size:11px;color:#9CA3AF;margin:0;">
              This digest was generated automatically by your n8n workflow. &nbsp;
              <a href="UNSUBSCRIBE_LINK" style="color:#9CA3AF;text-decoration:underline;">Unsubscribe</a>
            </p>
          </td>
        </tr>

      </table>
    </td></tr>
  </table>
</body>
</html>`;

return [{
  json: {
    html,
    subject:      `Your Daily AI Digest — ${today}`,
    articleCount: totalArticles,
    generatedAt:  new Date().toISOString(),
  }
}];

const articles = $input.all();

const grouped = {};

for (const item of articles) {
  const source = $('Limit').first().json.creator || 'General';
  const summary = item.json.output || item.json.text || '';
  const title   = $('Limit').first().json.title || '';
  const link    = $('Limit').first().json.link  || '';

  if (!grouped[source]) {
    grouped[source] = [];
  }

  grouped[source].push({
    title,
    link,
    summary
  });
}

const categories = Object.keys(grouped).map(category => ({
  category,
  articles: grouped[category]
}));

return [{ json: { categories } }];
